import{_ as t,o as r,c as l,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2018-Apr-12:: Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-Apr-12:: Ceph Performance Weekly","date":"2018-04-12T00:00:00.000Z","updated":"2018-04-13T00:00:00.000Z","tags":["Ceph","性能优化","分布式存储","RocksDB","Seastar"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-Apr-12_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-Apr-12_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),o={name:"posts/2018/2018-Apr-12_-_-_Ceph_Performance_Weekly.md"};function i(n,e,p,a,_,g){return r(),l("div",null,[...e[0]||(e[0]=[s("<p>本次会议主要讨论了 Ceph 存储系统在性能优化、功能开发以及相关技术问题。以下是会议的关键细节和决定的事项：</p><p><strong>关键细节</strong>：</p><ul><li><strong>Pull Requests</strong>： 讨论了 etherpad 加载问题，并建议开始处理 Pull Requests。</li><li><strong>RocksDB2</strong>： 更新了 RocksDB2 的当前上游版本，并讨论了相关 bug 和性能测试。</li><li><strong>Beast</strong>： 讨论了将 CivetWeb 替换为 Beast 的方案，以优化性能和资源消耗。</li><li><strong>性能测试</strong>： 讨论了性能测试的重要性，并分享了相关测试结果。</li><li><strong>Buffer List</strong>： 讨论了 Buffer List 的优化方案，包括使用 Small Vector 和改进内存管理。</li><li><strong>CRC 优化</strong>： 讨论了 CRC 优化方案，并建议移除 Buffer List 中的 CRC 相关功能。</li><li><strong>C-Store</strong>： 讨论了 C-Store 的规划，包括对象存储接口和事务协议。</li><li><strong>Seastar</strong>： 讨论了 Seastar 的性能优化和功能开发。</li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li><strong>性能优化</strong>： 讨论了 Ceph 存储系统中各个组件的性能优化方案，包括 RocksDB、Buffer List、网络协议等。</li><li><strong>功能开发</strong>： 讨论了 Ceph 存储系统中新功能的开发，例如 C-Store、对象存储接口等。</li><li><strong>技术问题</strong>： 讨论了 Ceph 存储系统中遇到的技术问题，例如 Buffer List 的内存管理、CRC 优化等。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>开始处理 Pull Requests。</li><li>更新 RocksDB2 的当前上游版本，并进行相关测试。</li><li>将 CivetWeb 替换为 Beast，优化性能和资源消耗。</li><li>对 Buffer List 进行优化，包括使用 Small Vector 和改进内存管理。</li><li>移除 Buffer List 中的 CRC 相关功能。</li><li>制定 C-Store 的规划，包括对象存储接口和事务协议。</li><li>继续优化 Seastar 的性能和功能。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>各参会人员根据会议讨论内容，继续进行相关开发工作。</li><li>定期召开会议，跟踪项目进展情况。</li></ul><p><strong>其他事项</strong>：</p><ul><li>讨论了 Ceph 存储系统中各个组件的优化方向和目标。</li><li>讨论了 Ceph 存储系统中遇到的技术难题和解决方案。</li><li>讨论了 Ceph 存储系统的未来发展方向。</li></ul>",11)])])}const f=t(o,[["render",i]]);export{u as __pageData,f as default};
